import{_ as e,o as a,c as t,ag as i}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"Commands and permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/commands.md","filePath":"en/shitbot/commands.md"}'),n={name:"en/shitbot/commands.md"};function d(o,s,l,r,p,c){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="commands-and-permissions" tabindex="-1">Commands and permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to &quot;Commands and permissions&quot;">​</a></h1><p><code>/shitbot whitelist</code> is available on every platform and requires <code>shitbot.admin</code>. Use <code>/shitbot whitelist add - Steve</code> for a whitelist entry without QQ, or <code>/shitbot whitelist add 123456789 Steve</code> to add a QQ binding directly. See <a href="/docs/en/shitbot/api.html#administrator-commands">Plugin API and whitelist management</a> for removal, pagination, and QQ lookups.</p><p>QQ examples on this page use <code>language: &quot;en_US&quot;</code>. For Chinese aliases, use <code>zh_CN</code> and the <a href="/docs/shitbot/commands.html">Chinese command reference</a>.</p><h2 id="administration-commands" tabindex="-1">Administration commands <a class="header-anchor" href="#administration-commands" aria-label="Permalink to &quot;Administration commands&quot;">​</a></h2><p>The main command is <code>/shitbot</code>, with alias <code>/sbot</code>.</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th><th>Permission</th></tr></thead><tbody><tr><td><code>/shitbot status</code></td><td>Show database, OneBot, and runtime status</td><td>None</td></tr><tr><td><code>/shitbot reload</code></td><td>Reload configuration, database, OneBot, images, and command services</td><td><code>shitbot.admin</code></td></tr><tr><td><code>/shitbot update</code></td><td>Download and install an update for this platform</td><td><code>shitbot.admin</code></td></tr><tr><td><code>/shitbot image</code></td><td>Generate an online status image manually</td><td><code>shitbot.admin</code></td></tr><tr><td><code>/shitbot editor</code></td><td>Create a short-lived, one-time editor login URL</td><td><code>shitbot.admin</code></td></tr><tr><td><code>/shitbot migrate easybot [EasyBot.db]</code></td><td>Import EasyBot bindings</td><td><code>shitbot.admin</code></td></tr></tbody></table><p>Spigot and Nukkit-MOT grant <code>shitbot.admin</code> to OPs by default. BungeeCord and Velocity check it through their platform permission systems.</p><p><code>/shitbot reload</code> creates a new runtime first and retains the old one if loading fails. Restart normally after JAR, Java, or TLS file changes.</p><h2 id="qq-binding" tabindex="-1">QQ binding <a class="header-anchor" href="#qq-binding" aria-label="Permalink to &quot;QQ binding&quot;">​</a></h2><p>Built-in English aliases:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bind &lt;Minecraft ID&gt; &lt;verification code&gt;</span></span>
<span class="line"><span>/bind &lt;Minecraft ID&gt; &lt;verification code&gt;</span></span></code></pre></div><p>The code is generated when an unbound player tries to join. The <code>binding</code> settings control QQ/Minecraft ID binding rules.</p><h2 id="online-status-and-inventories" tabindex="-1">Online status and inventories <a class="header-anchor" href="#online-status-and-inventories" aria-label="Permalink to &quot;Online status and inventories&quot;">​</a></h2><p>Built-in English commands:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server status</span></span>
<span class="line"><span>online players</span></span>
<span class="line"><span>inventory</span></span>
<span class="line"><span>my inventory</span></span>
<span class="line"><span>inventory &lt;Minecraft ID&gt;</span></span>
<span class="line"><span>my inventory &lt;Minecraft ID&gt;</span></span></code></pre></div><p>When a Minecraft ID is supplied, ShitBot verifies that it belongs to the sender&#39;s QQ account. You cannot query another user&#39;s character.</p><h2 id="tps" tabindex="-1">TPS <a class="header-anchor" href="#tps" aria-label="Permalink to &quot;TPS&quot;">​</a></h2><p>Configure TPS in <code>commands.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>Aliases, success text, and failure text are under <code>console.tps</code> in the selected language file.</p><ul><li>Standalone servers and Nukkit-MOT query locally.</li><li>Proxies can specify a default backend in <code>server</code>.</li><li>Group members can append a backend, for example <code>TPS survival</code>.</li><li>An empty <code>permission</code> skips the game permission check, but group restrictions and cooldowns still apply.</li></ul><h2 id="qq-shortcuts" tabindex="-1">QQ shortcuts <a class="header-anchor" href="#qq-shortcuts" aria-label="Permalink to &quot;QQ shortcuts&quot;">​</a></h2><p>Define each shortcut under <code>shortcuts</code> in <code>commands.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">shortcuts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  luckperms-editor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lp editor&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shitbot.admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    allow-unbound</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;backend&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    capture-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><p>Built-in aliases and reply templates are under <code>console.shortcuts.&lt;name&gt;</code> in the language file. For a new custom shortcut without a corresponding language entry, <code>aliases</code>, <code>message</code>, and <code>failed</code> in <code>commands.yml</code> are fallbacks.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><code>aliases</code></td><td>Trigger text in QQ</td></tr><tr><td><code>command</code></td><td>Console command without the leading <code>/</code></td></tr><tr><td><code>permission</code></td><td>Game permission required for the bound character; empty skips the game permission check</td></tr><tr><td><code>allow-unbound</code></td><td>Allow unbound QQ accounts; off by default</td></tr><tr><td><code>target</code></td><td><code>backend</code> runs on a Bukkit backend; <code>proxy</code> runs on BungeeCord/Velocity</td></tr><tr><td><code>server</code></td><td>Default backend; if empty, prefer the bound character&#39;s current backend</td></tr><tr><td><code>capture-seconds</code></td><td>Time to wait for and collect new console log output</td></tr></tbody></table><p>An empty <code>permission</code> still requires a bound character by default. Only an explicit <code>allow-unbound: true</code> permits unbound group members; use it carefully because it weakens the permission boundary.</p><p>Group members can override <code>server</code> by appending a backend:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lp editor survival</span></span></code></pre></div><h2 id="advanced-qq-image-commands" tabindex="-1">Advanced QQ image commands <a class="header-anchor" href="#advanced-qq-image-commands" aria-label="Permalink to &quot;Advanced QQ image commands&quot;">​</a></h2><p>Advanced templates do not register commands themselves. Declare each group entry explicitly under <code>image-templates.commands</code> in <code>commands.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">image-templates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    player-card</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      aliases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my card&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;player-card&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      player-source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;argument&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      target-server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;survival&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shitbot.image.player-card&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      cooldown-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      usage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%at% Usage: my card &lt;bound character&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      failed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%at% Image generation failed: %result%&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><code>aliases</code></td><td>Group triggers; avoid conflicts with built-in commands, TPS, or shortcuts</td></tr><tr><td><code>template</code></td><td>Published template ID</td></tr><tr><td><code>player-source</code></td><td><code>bound</code> selects the most recently bound character; <code>argument</code> verifies the supplied character belongs to the sender; <code>none</code> does not read bindings</td></tr><tr><td><code>target-server</code></td><td>Spigot backend handling permissions and PAPI in proxy deployments</td></tr><tr><td><code>permission</code></td><td>Permission required for the selected character; empty skips the check</td></tr><tr><td><code>cooldown-seconds</code></td><td>Separate cooldown for this template command, keyed by group and QQ</td></tr><tr><td><code>usage</code> / <code>failed</code></td><td>Invalid-argument and rendering-failure replies; support <code>%at%</code>, <code>%result%</code>, <code>%command%</code>, and <code>%server%</code></td></tr></tbody></table><p>Permission requests only check permissions; they do not execute console commands. <code>player-source: none</code> with a nonempty <code>permission</code> cannot authorize a request because no character is available to check. Enable <code>custom-image-templates.enabled: true</code> in <code>config.yml</code> as well. See <a href="/docs/en/shitbot/image-templates.html">Image rendering and advanced templates</a>.</p><h2 id="permission-resolution" tabindex="-1">Permission resolution <a class="header-anchor" href="#permission-resolution" aria-label="Permalink to &quot;Permission resolution&quot;">​</a></h2><p>For a shortcut with a <code>permission</code>, a Spigot backend checks:</p><ol><li>Bukkit permissions if the character is online.</li><li>LuckPerms, then Vault, then offline OP status if the character is offline.</li></ol><p>Proxy-local commands use proxy permissions; LuckPerms on the proxy can provide offline permissions. Nukkit-MOT uses its platform permissions for online characters and LuckPerms, if installed, for offline ones.</p><h2 id="command-output" tabindex="-1">Command output <a class="header-anchor" href="#command-output" aria-label="Permalink to &quot;Command output&quot;">​</a></h2><p>Before executing a shortcut, ShitBot records the log position. After <code>capture-seconds</code>, it reads newly appended content:</p><ul><li>Bukkit reads <code>logs/latest.log</code>.</li><li>Nukkit-MOT reads <code>logs/server.log</code>.</li><li>Original log files are not modified.</li><li>Each reply retains at most 100 lines and 4,000 characters.</li><li>Player chat, joins/leaves, and command execution logs are removed from the reply copy.</li><li>Player names, UUIDs, IPs, tokens, passwords, and database addresses are redacted in the reply copy.</li></ul><p>If execution succeeds without new log output, the bot says so explicitly.</p><h2 id="applying-changes" tabindex="-1">Applying changes <a class="header-anchor" href="#applying-changes" aria-label="Permalink to &quot;Applying changes&quot;">​</a></h2><p>After saving <code>commands.yml</code> or a language file:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/shitbot reload</span></span></code></pre></div><p>For proxy/backend deployments, finish editing both sides before reloading each instance. Restart after changing transport addresses, certificates, or firewall settings.</p>`,46)])])}const m=e(n,[["render",d]]);export{k as __pageData,m as default};
